head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.pageId = "ULDTMS03170";
scwin.scrollTop = "";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 목록을 최초 조회하고 페이지 리스트를 초기화(숨김)한다.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = function() {
    try {

                    // 조회
                    scwin.fnSearch("Y", 1);
                    // 초기화
                    pgl_list.hide();

    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDTMS03170.onpageload" });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
            /**
             * @method
             * @name btn_search_onclick
             * @description [조회] 버튼 클릭 — 목록을 1페이지부터 재조회한다(총건수 포함).
             * @param {Object} e 이벤트 객체
             * @returns {void}
             * @hidden N
             * @example scwin.btn_search_onclick(e);
             */
            scwin.btn_search_onclick = function (e) {

                scwin.fnSearch("Y", 1);
            };

            /**
             * @method
             * @name sbx_page_onchange
             * @description 한 페이지 건수 변경 — 목록을 1페이지부터 재조회한다(총건수 포함).
             * @param {Object} info 선택 변경 정보 객체
             * @returns {void}
             * @hidden N
             * @example scwin.sbx_page_onchange(info);
             */
            scwin.sbx_page_onchange = function (info) {

                scwin.fnSearch("Y", 1);
            };

            /**
             * @method
             * @name pgl_list_onclick
             * @description 페이지 번호 클릭 — 해당 페이지의 목록을 조회한다(총건수 미조회).
             * @param {Number} index 클릭한 페이지 번호
             * @returns {void}
             * @hidden N
             * @example scwin.pgl_list_onclick(1);
             */
            scwin.pgl_list_onclick = function (index) {

                scwin.fnSearch("N", index);
            };

            /**
             * @method
             * @name ibx_formCd_onkeyup
             * @description 서식번호 입력란 키 입력 — Enter 키 입력 시 목록을 1페이지부터 재조회한다.
             * @param {Object} e 이벤트 객체
             * @returns {void}
             * @hidden N
             * @example scwin.ibx_formCd_onkeyup(e);
             */
            scwin.ibx_formCd_onkeyup = function (e) {

                if (e.key === "Enter") {                    
                    scwin.fnSearch("Y", 1);
                }
            };

            /**
             * @method
             * @name ibx_formKorNm_onkeyup
             * @description 서식명 입력란 키 입력 — Enter 키 입력 시 목록을 1페이지부터 재조회한다.
             * @param {Object} e 이벤트 객체
             * @returns {void}
             * @hidden N
             * @example scwin.ibx_formKorNm_onkeyup(e);
             */
            scwin.ibx_formKorNm_onkeyup = function (e) {

                if (e.key === "Enter") {                    
                    scwin.fnSearch("Y", 1);
                }
            };

            /**
             * @method
             * @name ibx_formVer_onkeyup
             * @description 서식버전 입력란 키 입력 — Enter 키 입력 시 목록을 1페이지부터 재조회한다.
             * @param {Object} e 이벤트 객체
             * @returns {void}
             * @hidden N
             * @example scwin.ibx_formVer_onkeyup(e);
             */
            scwin.ibx_formVer_onkeyup = function (e) {

                if (e.key === "Enter") {                    
                    scwin.fnSearch("Y", 1);
                }
            };

            /**
             * @method
             * @name grd_list_oncellclick
             * @description 목록 셀 클릭 — 서식명(formKorNm) 컬럼 클릭 시 그리드 위치를 저장하고 기재상 주의 관리 상세 팝업(ULDTMS03180)을 연다. 저장 후 복귀 시 스크롤 위치를 복원하며 재조회하고, 취소 시 저장한 위치 정보를 삭제한다.
             * @param {Number} rowIndex 클릭한 행 인덱스
             * @param {Number} columnIndex 클릭한 컬럼 인덱스
             * @param {String} columnId 클릭한 컬럼 ID
             * @returns {void}
             * @hidden N
             * @example scwin.grd_list_oncellclick(0, 1, "formKorNm");
             */
            scwin.grd_list_oncellclick = async function (rowIndex, columnIndex, columnId) {

                if (columnId === "formKorNm") {                    
                    const params = {};
                    params.formCd = dlt_list.getCellData(rowIndex, "formCd");
                    params.formKorNm = dlt_list.getCellData(rowIndex, "formKorNm");
                    params.formVer = dlt_list.getCellData(rowIndex, "formVer");
                    params.storageId = scwin.pageId;

                    // 위치 정보 저장
                    $c.tms.setKeywordSave(scwin.pageId, grd_list, dma_search);                                        

                    const url_ = "/ui/TMS/ULDTMS03180.xml";
                    const options = {
                        id: "ULDTMS03180_POP",
                        popupName: "기재상의 주의 관리 상세",
                        width: "600",
                        height: "320",
                        frameModal: "top"
                    };

                    const result = await $c.win.openPopup(url_, options, params);
                    if (!$c.util.isEmpty(result) && result.refreshYn === "Y") {
                        //  그리드 위치 처리
                        if (!$c.util.isEmpty(result.storageId)) {                        
                            scwin.scrollTop = $c.tms.getKeywordSave(result.storageId, dma_search); 
                        }
                        scwin.fnSearch();
                    } else {
                        $c.tms.delKeyword(scwin.pageId);
                    }
                }
            };

///////// 4. 서브미션 콜백 영역 /////////
            /**
             * @method
             * @name sbm_list_submitdone
             * @description 목록 조회(sbm_list) 콜백 — 페이지별 시작 행 번호를 계산해 그리드에 설정하고, 최초 조회 시에만 총건수·페이지 리스트를 표시하며, 저장된 스크롤 위치가 있으면 복원한다.
             * @param {Object} e 이벤트 객체
             * @returns {void}
             * @hidden N
             * @example (sbm_list ev:submitdone 바인딩으로 자동 호출)
             */
            scwin.sbm_list_submitdone = function (e) {

                // 조회 성공인 경우
                const result = e.responseJSON;
                if (result.success) {
                    const obj = result.body;

                    // 시작 번호 계산 (페이지별 연속 번호)
                    const currentPage = parseInt(dma_search.get("page")) || 1;
                    const pageSize = parseInt(dma_search.get("size")) || 10;                                                    
                    const startIndex = (currentPage - 1) * pageSize;                   

                    // 페이지별 시작 번호 계산 및 그리드에 설정                    
                    grd_list.setStartRowNumber(startIndex);

                    const firstYn = dma_search.get("totalYn");
                    let totalCnt = 0;

                    // 최초 조회일 경우에만 전체 건수를 구하여 전역변수에 담는다.
                    if (firstYn === "Y") {
                        if (!$c.util.isEmpty(obj.totalCount)) {
                            tbx_totCnt.setValue($c.num.formatNumber(obj.totalCount));
                            totalCnt = parseInt(obj.totalCount) || 0;
                        }        

                        // 데이터가 있는 경우에만 페이지 리스트 표시
                        if (totalCnt > 0) { 
                            pgl_list.setCount(obj.totalPages);
                            pgl_list.show();
                        } else {
                            pgl_list.hide();
                        }            
                    }

                    // 재조회 여부 체크
                    if (!$c.util.isEmpty(scwin.scrollTop)) {
                        grd_list.setScrollTop(scwin.scrollTop);                        
                        scwin.scrollTop = "";
                    }                    
                } else {
                    $c.win.alert(result.message);
                }
            };

///////// 5. 일반/업무 함수 영역 /////////
            /**
             * @method
             * @name fnSearch
             * @description 목록 조회 — 총건수 조회 여부·페이지 번호·한 페이지 건수를 dma_search 에 설정하고 목록(sbm_list)을 조회한다.
             * @param {String} totYn 총건수 조회 여부("Y"/"N")
             * @param {Number} index 조회할 페이지 번호
             * @returns {void}
             * @hidden N
             * @example scwin.fnSearch("Y", 1);
             */
            scwin.fnSearch = function (totYn, index) {

                dma_search.set("totalYn", totYn);
                dma_search.set("page", index);
                dma_search.set("size", sbx_page.getValue());

                // 조회 
                $c.sbm.execute(sbm_list, dma_search.getJSON());
            };
